binding.script:
# SOM-J CENTRAL PYLON
  if ((getprop("/sim/multiplay/generic/bool[26]")) 
 and !getprop("/sim/launching-SOMJ1")) {
  var SOMJ1Count = getprop("sim/ai/submodels/SOM-J-1-number");
  if (SOMJ1Count > 0 and SOMJ1Count <= 1) {
    setprop("/sim/launching-SOMJ1", 1);

    var mpIndex = 11 + SOMJ1Count;  # Se (11 + 1) = 12 allora "int[12]"
    var propPath = "sim/multiplay/generic/int[" ~ mpIndex ~ "]";
    setprop(propPath, 1);

    settimer(func() { setprop(propPath, 0); }, 0.2);
    settimer(func() {
      setprop("sim/ai/submodels/SOM-J-1-number", SOMJ1Count - 1);
      setprop("/sim/launching-SOMJ1", 0);
    }, 0.3);
  }
}

